import { Control, FrameworkSlug } from './types'

// ---------------------------------------------------------------------------
// The control library.
//
// Shared/overlapping controls (MFA, patch management, backup & recovery,
// incident response plan, access reviews, encryption at rest/in transit,
// supplier due diligence, security awareness training, asset inventory,
// logging & monitoring, business continuity plan, vendor contracts/DPAs)
// are tagged with MULTIPLE frameworkSlugs so they appear once in the
// control library but satisfy every framework workspace they're relevant
// to — editing status/evidence on one of these updates it everywhere.
//
// CE+ (cyber-essentials-plus) deliberately reuses the Cyber Essentials
// controls (same five technical themes) rather than duplicating them —
// see the comment above the Cyber Essentials section.
// ---------------------------------------------------------------------------

let counter = 0
function nextId(prefix: string): string {
  counter += 1
  return `${prefix}-${String(counter).padStart(3, '0')}`
}

function mk(
  prefix: string,
  frameworkSlugs: FrameworkSlug[],
  domain: string,
  title: string,
  description: string,
  guidance: string,
  evidenceExample: string,
  lightDepth?: boolean,
): Control {
  return {
    id: nextId(prefix),
    frameworkSlugs,
    domain,
    title,
    description,
    guidance,
    evidenceExample,
    ...(lightDepth ? { lightDepth: true } : {}),
  }
}

