export function getControlsForFramework(slug: FrameworkSlug): Control[] {
  return CONTROLS.filter((c) => c.frameworkSlugs.includes(slug))
}

export function getControlById(id: string): Control | undefined {
  return CONTROLS.find((c) => c.id === id)
}
